const incoming = $input.first()?.json ?? {};
const body = incoming.body && typeof incoming.body === 'object' ? incoming.body : incoming;
const envelope = body.input && typeof body.input === 'object' ? body.input : body;
const source = envelope.data && typeof envelope.data === 'object' ? envelope.data : envelope;
const taskType = envelope.task_type ?? 'customer_feedback';
const fixtureCase = source.fixture_case ?? envelope.fixture_case ?? body.fixture_case ?? body.case ?? 'B';

const input_contract = {
  customer_identity: source.customer_identity ?? source.customer_name ?? '',
  message_text: source.message_text ?? source.feedback ?? '',
  urgency_signal: source.urgency_signal ?? source.rating ?? null,
  owner_email: source.owner_email ?? null
};
const document_contract = {
  applicant: source.applicant ?? '',
  document_type: source.document_type ?? '',
  due_date: source.due_date ?? ''
};

const missing = [];
let output = {};
let validation_error = null;
if (taskType === 'customer_feedback') {
  if (typeof input_contract.customer_identity !== 'string' || input_contract.customer_identity.trim() === '') missing.push('customer_identity');
  if (typeof input_contract.message_text !== 'string' || input_contract.message_text.trim() === '') missing.push('message_text');
  if (input_contract.urgency_signal !== null && typeof input_contract.urgency_signal !== 'number') missing.push('urgency_signal(number)');
  if (fixtureCase === 'A') {
    output = { summary: '物流延遲且客服回覆時間過長', reply_draft: '感謝你的回饋，我們會檢查物流通知流程並改善客服回覆時間。', needs_review: true };
  } else if (fixtureCase === 'B') {
    output = { summary: '客戶回饋問題已獲得處理並表示感謝', reply_draft: '謝謝你的回饋，很高興這次的問題已經順利解決。', needs_review: false };
  } else if (fixtureCase === 'C') {
    output = { summary: '物流延遲且客服回覆時間過長', reply_draft: '請先確認這段回覆內容，再決定是否送出。', needs_review: 'false' };
    validation_error = 'needs_review must be boolean; received string';
  } else {
    validation_error = `unknown_fixture_case: ${fixtureCase}`;
  }
} else if (taskType === 'document_request') {
  if (typeof document_contract.applicant !== 'string' || document_contract.applicant.trim() === '') missing.push('applicant');
  if (typeof document_contract.document_type !== 'string' || document_contract.document_type.trim() === '') missing.push('document_type');
  if (!/^\d{4}-\d{2}-\d{2}$/.test(document_contract.due_date)) missing.push('due_date(YYYY-MM-DD)');
  if (missing.length === 0) {
    output = { summary: `文件申請：${document_contract.applicant}／${document_contract.document_type}`, reply_draft: '已收到文件申請，請依 n8n 分流結果處理。', needs_review: false };
  }
} else {
  validation_error = `unsupported_task_type: ${taskType}`;
}

if (missing.length > 0 && !validation_error) {
  validation_error = `missing_or_invalid: ${missing.join(', ')}`;
}
const contract_status = validation_error ? 'invalid' : 'valid';
return [{ json: { fixture_case: fixtureCase, task_type: taskType, source_platform: envelope.source_platform ?? 'make', evidence_mode: envelope.evidence_mode ?? 'SIMULATED', input_contract, document_contract, ...output, contract_status, validation_error } }];

const item = $input.first().json;
const subject = item.task_type === 'document_request' ? `文件申請：${item.document_contract.applicant}` : `客服回饋：${item.input_contract.customer_identity}`;
return [{ json: { ...item, route: 'google_docs', artifact: { type: 'google_docs', status: 'simulated_created', title: subject, body: `摘要：${item.summary}\\n\\n回覆草稿：${item.reply_draft}` } } }];
